import hmac
import hashlib
import os
import unicodedata
import time
import json
from flask import Flask, request, jsonify, g, abort

app = Flask(__name__)

SERVER_SECRET = os.environ.get('SERVER_SECRET', os.urandom(32).hex())

# User database with role assignments
USER_DB = {
    'admin': {'role': 'administrator', 'active': True},
    'alice': {'role': 'viewer', 'active': True},
    'bob': {'role': 'editor', 'active': True},
    'carlos': {'role': 'viewer', 'active': True},
    '\u01b0\u0323c': {'role': 'administrator', 'active': True},  # Vietnamese char admin
}

ROLE_PERMISSIONS = {
    'administrator': ['read', 'write', 'delete', 'admin'],
    'editor': ['read', 'write'],
    'viewer': ['read'],
}

def normalize_username(username):
    """Normalize username for consistent lookup and token generation.
    NFKC normalization ensures equivalent Unicode representations
    map to the same canonical form. Applied BEFORE token operations."""
    return unicodedata.normalize('NFKC', username).lower()

def generate_token(username):
    """Generate an HMAC-signed authentication token.
    Username is normalized BEFORE being included in the token."""
    # Normalize before signing to ensure token username matches lookup
    canonical = normalize_username(username)
    timestamp = int(time.time()).to_bytes(4, 'big')
    username_bytes = canonical.encode('utf-8')
    length = len(username_bytes).to_bytes(2, 'big')
    payload = timestamp + length + username_bytes
    mac = hmac.new(SERVER_SECRET.encode(), payload, hashlib.sha256).digest()
    return (payload + mac).hex()

def verify_token(token_hex):
    """Verify token HMAC and extract username.
    The username in the token is already normalized."""
    try:
        token = bytes.fromhex(token_hex)
    except (ValueError, TypeError):
        return None, 'Invalid token format'

    if len(token) < 38:
        return None, 'Token too short'

    timestamp = int.from_bytes(token[0:4], 'big')
    current_time = int(time.time())

    if abs(current_time - timestamp) > 3600:
        return None, 'Token expired'

    username_len = int.from_bytes(token[4:6], 'big')

    if username_len > 256 or username_len == 0:
        return None, 'Invalid username length'

    expected_total = 4 + 2 + username_len + 32
    if len(token) != expected_total:
        return None, 'Invalid token length'

    payload = token[0:6 + username_len]
    provided_mac = token[6 + username_len:]

    expected_mac = hmac.new(
        SERVER_SECRET.encode(), payload, hashlib.sha256
    ).digest()

    if not hmac.compare_digest(provided_mac, expected_mac):
        return None, 'Invalid signature'

    # Extract username (already normalized when token was created)
    username_bytes = token[6:6 + username_len]
    username = username_bytes.decode('utf-8')
    return username, None

def get_user_record(username):
    """Look up user by normalized username."""
    normalized = normalize_username(username)
    for db_user, record in USER_DB.items():
        if normalize_username(db_user) == normalized:
            return db_user, record
    return None, None

def require_auth(f):
    """Authentication decorator - verifies token signature."""
    def wrapper(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            abort(401)
        token = auth_header[7:]
        username, error = verify_token(token)
        if error:
            abort(401)
        g.token_username = username
        return f(*args, **kwargs)
    wrapper.__name__ = f.__name__
    return wrapper

def require_permission(permission):
    """Authorization decorator - checks user permissions."""
    def decorator(f):
        def wrapper(*args, **kwargs):
            # Token already contains normalized username
            db_user, record = get_user_record(g.token_username)
            if not record or not record.get('active'):
                abort(403)
            role = record['role']
            permissions = ROLE_PERMISSIONS.get(role, [])
            if permission not in permissions:
                abort(403)
            g.effective_user = db_user
            g.permissions = permissions
            return f(*args, **kwargs)
        wrapper.__name__ = f.__name__
        return wrapper
    return decorator

@app.route('/api/token', methods=['POST'])
def get_token():
    """Issue a token for a username (simplified - no password for demo)."""
    data = request.get_json(silent=True)
    if not data or 'username' not in data:
        return jsonify({'error': 'Username required'}), 400
    username = data['username']
    # Verify user exists before issuing token
    db_user, record = get_user_record(username)
    if not record or not record.get('active'):
        return jsonify({'error': 'Unknown user'}), 404
    # Issue token with normalized username
    token = generate_token(username)
    return jsonify({'token': token, 'user': db_user})

@app.route('/api/documents', methods=['GET'])
@require_auth
@require_permission('read')
def list_documents():
    return jsonify({'documents': ['doc1', 'doc2', 'doc3'], 'user': g.effective_user})

@app.route('/api/admin/users', methods=['GET'])
@require_auth
@require_permission('admin')
def admin_list_users():
    return jsonify({'users': list(USER_DB.keys()), 'requested_by': g.effective_user})

@app.route('/api/admin/delete_user', methods=['POST'])
@require_auth
@require_permission('admin')
def admin_delete_user():
    data = request.get_json(silent=True)
    if not data or 'target_user' not in data:
        return jsonify({'error': 'target_user required'}), 400
    target = data.get('target_user', '')
    if target in USER_DB:
        del USER_DB[target]
        return jsonify({'deleted': target})
    return jsonify({'error': 'User not found'}), 404

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000, debug=False)
